def zip_longest_sum(a, b):
    n = max(len(a), len(b))
    return [a[i] if i < len(a) else 0 + b[i] if i < len(b) else 0 for i in range(n)]

def zip_longest_sum(a, b):
    n = max(len(a), len(b))
    return [a[i] + b[i] if i < len(a) and i < len(b) else (a[i] if i < len(a) else b[i]) for i in range(n)]

def zip_longest_sum(a, b):
    result = []
    len_a = len(a)
    len_b = len(b)
    max_len = len_a if len_a > len_b else len_b
    for i in range(max_len):
        val = 0
        if i < len_a:
            val += a[i]
        if i < len_b:
            val += b[i]
        result.append(val)
    return result
